import React from 'react';

function Discover() {
  return (
    <div className="discover-container" style={{ padding: '20px' }}>
      <h2>🔍 Discover</h2>
      <p>Explore and discover new features of the Solidarity Platform.</p>
      <div style={{ 
        padding: '20px', 
        background: 'linear-gradient(135deg, #667eea33, #764ba233)', 
        borderRadius: '12px',
        marginTop: '20px'
      }}>
        <h3>Coming Soon</h3>
        <p>Discover integrations, community features, and more.</p>
      </div>
    </div>
  );
}

export default Discover;
